<script setup lang="ts">
import { onMounted, ref } from 'vue';import { apiSeguridad } from '@/utils/seguridad'
const rows=ref<any[]>([]),modulo=ref(''),accion=ref(''),descripcion=ref(''),error=ref('');const cargar=async()=>{try{rows.value=await apiSeguridad('/permisos')}catch(e:any){error.value=e.message}};const guardar=async()=>{try{await apiSeguridad('/permisos',{method:'POST',body:JSON.stringify({modulo:modulo.value,accion:accion.value,descripcion:descripcion.value})});modulo.value=accion.value=descripcion.value='';cargar()}catch(e:any){error.value=e.message}};onMounted(cargar)
</script><template><div class="admin-page"><section class="page-hero admin-hero d-flex align-center justify-space-between ga-4 mb-6"><div class="d-flex align-center ga-4"><VAvatar color="primary" variant="tonal" rounded size="58"><VIcon icon="tabler-key" size="30"/></VAvatar><div><div class="process-kicker">Seguridad y acceso</div><h1 class="text-h4 font-weight-bold mb-1">Permisos</h1><p class="text-medium-emphasis mb-0">Control granular de acciones disponibles por módulo.</p></div></div><VChip color="primary" variant="tonal" size="large">{{rows.length}} permisos</VChip></section><VCard class="module-card mb-6"><VCardItem class="module-header"><VCardTitle><VIcon icon="tabler-circle-plus" class="me-2"/>Registrar permiso</VCardTitle></VCardItem><VCardText class="pa-6"><VAlert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</VAlert><VRow align="center"><VCol cols="12" md="3"><VTextField v-model="modulo" label="Módulo" prepend-inner-icon="tabler-box" hide-details/></VCol><VCol cols="12" md="3"><VTextField v-model="accion" label="Acción" prepend-inner-icon="tabler-bolt" hide-details/></VCol><VCol cols="12" md="4"><VTextField v-model="descripcion" label="Descripción" prepend-inner-icon="tabler-notes" hide-details/></VCol><VCol cols="12" md="2"><VBtn block size="large" prepend-icon="tabler-plus" @click="guardar">Agregar</VBtn></VCol></VRow></VCardText></VCard><VCard class="module-card"><VCardItem class="module-header"><VCardTitle>Catálogo de permisos</VCardTitle></VCardItem><VCardText class="pa-6"><VDataTable :items="rows" :headers="[{title:'Módulo',key:'modulo'},{title:'Acción',key:'accion'},{title:'Descripción',key:'descripcion'}]" class="product-table"><template #item.modulo="{item}"><VChip color="primary" variant="tonal" size="small">{{item.modulo}}</VChip></template><template #item.accion="{item}"><code class="admin-code">{{item.accion}}</code></template></VDataTable></VCardText></VCard></div></template>
